import { useRef, useState } from "react";
function TooltipDemo() {
const btnRef = useRef<HTMLButtonElement>(null);
const { x, y, width, height } = useElementBounding(btnRef);
const [show, setShow] = useState(false);
return (
<div style={{ padding: 24, minHeight: "200vh" }}>
<div style={{ marginTop: 300 }}>
<button
ref={btnRef}
onMouseEnter={() => setShow(true)}
onMouseLeave={() => setShow(false)}
style={{
padding: "8px 16px",
background: "#4f46e5",
color: "#fff",
border: "none",
borderRadius: 6,
cursor: "pointer",
}}
>
Hover me (scroll to test)
</button>
</div>
{show && (
<div
style={{
position: "fixed",
left: x + width / 2,
top: y - 8,
transform: "translate(-50%, -100%)",
padding: "6px 12px",
background: "#1e293b",
color: "#fff",
borderRadius: 6,
fontSize: 13,
whiteSpace: "nowrap",
pointerEvents: "none",
zIndex: 1000,
}}
>
I follow the button even on scroll!
<div
style={{
position: "absolute",
bottom: -4,
left: "50%",
transform: "translateX(-50%) rotate(45deg)",
width: 8,
height: 8,
background: "#1e293b",
}}
/>
</div>
)}
</div>
);
}
Because useElementBounding
updates on scroll, the tooltip position stays correct even as the user scrolls the page -- without any extra event listeners on your part.
4. Building a Scratch Pad with useScratch
The Manual Way
A scratch interaction -- where the user drags across a surface and you track the starting point, current position, and deltas -- requires handling both mouse and touch events, computing element-relative coordinates, and tracking timing:
import { useEffect, useRef, useState } from "react";
interface ScratchState {
isScratching: boolean;
startX: number;
startY: number;
x: number;
y: number;
dx: number;
dy: number;
}
function ManualScratchPad() {
const canvasRef = useRef<HTMLDivElement>(null);
const [state, setState] = useState<ScratchState>({
isScratching: false,
startX: 0,
startY: 0,
x: 0,
y: 0,
dx: 0,
dy: 0,
});
const [lines, setLines] = useState<Array<{ x: number; y: number }>>([]);
const scratchingRef = useRef(false);
useEffect(() => {
const el = canvasRef.current;
if (!el) return;
const getRelativePos = (clientX: number, clientY: number) => {
const rect = el.getBoundingClientRect();
return {
x: clientX - rect.left,
y: clientY - rect.top,
};
};
const onMouseDown = (e: MouseEvent) => {
e.preventDefault();
const pos = getRelativePos(e.clientX, e.clientY);
scratchingRef.current = true;
setState({
isScratching: true,
startX: pos.x,
startY: pos.y,
x: pos.x,
y: pos.y,
dx: 0,
dy: 0,
});
setLines([pos]);
};
const onMouseMove = (e: MouseEvent) => {
if (!scratchingRef.current) return;
const pos = getRelativePos(e.clientX, e.clientY);
setState((prev) => ({
...prev,
dx: pos.x - prev.x,
dy: pos.y - prev.y,
x: pos.x,
y: pos.y,
}));
setLines((prev) => [...prev, pos]);
};
const onMouseUp = () => {
scratchingRef.current = false;
setState((prev) => ({ ...prev, isScratching: false }));
};
el.addEventListener("mousedown", onMouseDown);
window.addEventListener("mousemove", onMouseMove);
window.addEventListener("mouseup", onMouseUp);
return () => {
el.removeEventListener("mousedown", onMouseDown);
window.removeEventListener("mousemove", onMouseMove);
window.removeEventListener("mouseup", onMouseUp);
};
}, []);
return (
<div style={{ padding: 24 }}>
<div
ref={canvasRef}
style={{
width: 400,
height: 300,
background: "#f1f5f9",
borderRadius: 8,
cursor: "crosshair",
position: "relative",
overflow: "hidden",
}}
>
<svg
style={{ position: "absolute", inset: 0 }}
width={400}
height={300}
>
{lines.length > 1 && (
<polyline
points={lines.map((p) => `${p.x},${p.y}`).join(" ")}
fill="none"
stroke="#4f46e5"
strokeWidth={3}
strokeLinecap="round"
strokeLinejoin="round"
/>
)}
</svg>
<p style={{ padding: 16, margin: 0, color: "#94a3b8" }}>
{state.isScratching ? "Drawing..." : "Draw here"}
</p>
</div>
</div>
);
}
This is already quite verbose, and it only handles mouse events -- no touch support. Adding touch means duplicating every handler for touchstart
, touchmove
, and touchend
. It also does not use requestAnimationFrame
, so rapid movements can overwhelm React's rendering.
With useScratch
useScratch
handles both mouse and touch events, computes element-relative coordinates, tracks timing, and batches state updates via requestAnimationFrame
. It returns a state object with isScratching
, x
, y
, dx
, dy
, elW
, elH
, and timestamps.
import { useScratch } from "@reactuses/core";
import { useRef, useState, useEffect } from "react";
function ScratchPad() {
const padRef = useRef<HTMLDivElement>(null);
const state = useScratch(padRef);
const [points, setPoints] = useState<Array<{ x: number; y: number }>>([]);
useEffect(() => {
if (state.isScratching && state.x !== undefined && state.y !== undefined) {
setPoints((prev) => [...prev, { x: state.x!, y: state.y! }]);
}
if (!state.isScratching) {
// Optionally clear on release
}
}, [state.isScratching, state.x, state.y]);
return (
<div style={{ padding: 24 }}>
<div
ref={padRef}
style={{
width: 400,
height: 300,
background: "#f1f5f9",
borderRadius: 8,
cursor: "crosshair",
position: "relative",
overflow: "hidden",
touchAction: "none",
}}
>
<svg
style={{ position: "absolute", inset: 0 }}
width={400}
height={300}
>
{points.length > 1 && (
<polyline
points={points.map((p) => `${p.x},${p.y}`).join(" ")}
fill="none"
stroke="#4f46e5"
strokeWidth={3}
strokeLinecap="round"
strokeLinejoin="round"
/>
)}
</svg>
<div style={{ padding: 16, color: "#94a3b8", position: "relative" }}>
{state.isScratching ? (
<span>
Drawing at ({Math.round(state.x ?? 0)},{" "}
{Math.round(state.y ?? 0)}) -- delta: (
{Math.round(state.dx ?? 0)}, {Math.round(state.dy ?? 0)})
</span>
) : (
"Draw here (mouse or touch)"
)}
</div>
</div>
<button
onClick={() => setPoints([])}
style={{
marginTop: 12,
padding: "8px 16px",
background: "#e2e8f0",
border: "none",
borderRadius: 6,
cursor: "pointer",
}}
>
Clear
</button>
</div>
);
}
Touch support, requestAnimationFrame
batching, and element-relative coordinate computation are all handled by the hook. You also get callbacks via the onScratchStart
, onScratch
, and onScratchEnd
options if you prefer event-driven patterns over reactive state.
Practical example: scratch-to-reveal card
A classic scratch-to-reveal effect where the user scratches off a covering layer:
import { useScratch } from "@reactuses/core";
import { useRef, useState, useCallback } from "react";
function ScratchToReveal() {
const coverRef = useRef<HTMLDivElement>(null);
const canvasRef = useRef<HTMLCanvasElement>(null);
const [revealed, setRevealed] = useState(false);
const state = useScratch(coverRef, {
onScratch: (s) => {
const canvas = canvasRef.current;
if (!canvas || !s.x || !s.y) return;
const ctx = canvas.getContext("2d");
if (!ctx) return;
ctx.globalCompositeOperation = "destination-out";
ctx.beginPath();
ctx.arc(s.x, s.y, 20, 0, Math.PI * 2);
ctx.fill();
// Check how much has been scratched
const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
const pixels = imageData.data;
let transparent = 0;
for (let i = 3; i < pixels.length; i += 4) {
if (pixels[i] === 0) transparent++;
}
const ratio = transparent / (pixels.length / 4);
if (ratio > 0.5) {
setRevealed(true);
}
},
});
const initCanvas = useCallback((el: HTMLCanvasElement | null) => {
if (!el) return;
(canvasRef as React.MutableRefObject<HTMLCanvasElement>).current = el;
const ctx = el.getContext("2d");
if (ctx) {
ctx.fillStyle = "#94a3b8";
ctx.fillRect(0, 0, el.width, el.height);
ctx.font = "16px sans-serif";
ctx.fillStyle = "#fff";
ctx.textAlign = "center";
ctx.fillText("Scratch here!", el.width / 2, el.height / 2);
}
}, []);
return (
<div
ref={coverRef}
style={{
width: 300,
height: 150,
position: "relative",
borderRadius: 12,
overflow: "hidden",
cursor: "crosshair",
touchAction: "none",
}}
>
{/* Hidden content */}
<div
style={{
position: "absolute",
inset: 0,
background: "linear-gradient(135deg, #4f46e5, #7c3aed)",
display: "flex",
alignItems: "center",
justifyContent: "center",
color: "#fff",
fontSize: 20,
fontWeight: 700,
}}
>
You won a prize!
</div>
{/* Scratch layer */}
{!revealed && (
<canvas
ref={initCanvas}
width={300}
height={150}
style={{ position: "absolute", inset: 0 }}
/>
)}
</div>
);
}
5. Picking Colors from the Screen with useEyeDropper
The Manual Way
The EyeDropper API is relatively new and only available in Chromium-based browsers. Using it directly means checking for support, handling the async nature of the picker, and dealing with the abort signal:
import { useState, useCallback } from "react";
function ManualColorPicker() {
const [color, setColor] = useState<string | null>(null);
const [error, setError] = useState<string | null>(null);
const isSupported =
typeof window !== "undefined" && "EyeDropper" in window;
const pickColor = useCallback(async () => {
if (!isSupported) {
setError("EyeDropper API is not supported in this browser");
return;
}
try {
const dropper = new (window as any).EyeDropper();
const result = await dropper.open();
setColor(result.sRGBHex);
setError(null);
} catch (e: any) {
if (e.name !== "AbortError") {
setError(e.message);
}
}
}, [isSupported]);
return (
<div style={{ padding: 24 }}>
<button
onClick={pickColor}
disabled={!isSupported}
style={{
padding: "8px 16px",
background: "#4f46e5",
color: "#fff",
border: "none",
borderRadius: 6,
cursor: isSupported ? "pointer" : "not-allowed",
opacity: isSupported ? 1 : 0.5,
}}
>
Pick a Color
</button>
{color && (
<div style={{ marginTop: 16, display: "flex", alignItems: "center", gap: 12 }}>
<div
style={{
width: 48,
height: 48,
borderRadius: 8,
background: color,
border: "1px solid #e2e8f0",
}}
/>
<code>{color}</code>
</div>
)}
{error && <p style={{ color: "#ef4444" }}>{error}</p>}
</div>
);
}
The boilerplate around feature detection, async handling, and error management is not terrible, but it adds up when you use it in multiple places.
With useEyeDropper
useEyeDropper
abstracts the EyeDropper API into a simple [isSupported, open]
tuple. The open
function returns a promise that resolves to { sRGBHex: string }
. If the API is not supported, isSupported
is false
and open
resolves with an empty string.
import { useEyeDropper } from "@reactuses/core";
import { useState } from "react";
function ColorPicker() {
const [isSupported, open] = useEyeDropper();
const [color, setColor] = useState<string | null>(null);
const pickColor = async () => {
const { sRGBHex } = await open();
if (sRGBHex) {
setColor(sRGBHex);
}
};
return (
<div style={{ padding: 24 }}>
{!isSupported && (
<p style={{ color: "#f59e0b" }}>
EyeDropper API is not supported in your browser.
</p>
)}
<button
onClick={pickColor}
disabled={!isSupported}
style={{
padding: "8px 16px",
background: "#4f46e5",
color: "#fff",
border: "none",
borderRadius: 6,
cursor: isSupported ? "pointer" : "not-allowed",
opacity: isSupported ? 1 : 0.5,
}}
>
Pick Color from Screen
</button>
{color && (
<div
style={{
marginTop: 16,
display: "flex",
alignItems: "center",
gap: 12,
}}
>
<div
style={{
width: 48,
height: 48,
borderRadius: 8,
background: color,
border: "1px solid #e2e8f0",
}}
/>
<code style={{ fontSize: 18 }}>{color}</code>
</div>
)}
</div>
);
}
Clean, declarative, and the support check is always available so you can show a fallback UI in unsupported browsers.
Practical example: color palette builder
Build a palette by picking colors from anywhere on screen:
import { useEyeDropper } from "@reactuses/core";
import { useState } from "react";
function PaletteBuilder() {
const [isSupported, open] = useEyeDropper();
const [palette, setPalette] = useState<string[]>([]);
const addColor = async () => {
const { sRGBHex } = await open();
if (sRGBHex) {
setPalette((prev) =>
prev.includes(sRGBHex) ? prev : [...prev, sRGBHex]
);
}
};
const removeColor = (hex: string) => {
setPalette((prev) => prev.filter((c) => c !== hex));
};
return (
<div style={{ padding: 24 }}>
<h3>Color Palette Builder</h3>
<button
onClick={addColor}
disabled={!isSupported}
style={{
padding: "8px 20px",
background: "#4f46e5",
color: "#fff",
border: "none",
borderRadius: 6,
cursor: "pointer",
marginBottom: 16,
}}
>
+ Pick Color
</button>
