6. Putting It All Together: An Interactive Canvas Tool
These hooks compose naturally. Here is an interactive drawing tool that combines mouse tracking, press detection, element bounding, scratch interaction, and a color picker:
import {
useMouse,
useMousePressed,
useElementBounding,
useScratch,
useEyeDropper,
} from "@reactuses/core";
import { useRef, useState, useEffect } from "react";
function InteractiveCanvasTool() {
const canvasRef = useRef<HTMLDivElement>(null);
const toolbarRef = useRef<HTMLDivElement>(null);
// Track mouse for the cursor preview
const mouse = useMouse(canvasRef);
// Detect press state for visual feedback
const [pressed] = useMousePressed(canvasRef);
// Track canvas position for absolute positioning of overlays
const canvasBounds = useElementBounding(canvasRef);
// Scratch state for drawing
const scratch = useScratch(canvasRef);
// Color picker
const [isEyeDropperSupported, openEyeDropper] = useEyeDropper();
// Drawing state
const [brushColor, setBrushColor] = useState("#4f46e5");
const [brushSize, setBrushSize] = useState(4);
const [strokes, setStrokes] = useState<
Array<{ points: Array<{ x: number; y: number }>; color: string; size: number }>
>([]);
const [currentStroke, setCurrentStroke] = useState<
Array<{ x: number; y: number }>
>([]);
// Accumulate points during a scratch
useEffect(() => {
if (scratch.isScratching && scratch.x !== undefined && scratch.y !== undefined) {
setCurrentStroke((prev) => [...prev, { x: scratch.x!, y: scratch.y! }]);
}
}, [scratch.isScratching, scratch.x, scratch.y]);
// Save stroke when scratching ends
useEffect(() => {
if (!scratch.isScratching && currentStroke.length > 1) {
setStrokes((prev) => [
...prev,
{ points: currentStroke, color: brushColor, size: brushSize },
]);
setCurrentStroke([]);
}
}, [scratch.isScratching, currentStroke, brushColor, brushSize]);
const pickColor = async () => {
const { sRGBHex } = await openEyeDropper();
if (sRGBHex) {
setBrushColor(sRGBHex);
}
};
const clearCanvas = () => {
setStrokes([]);
setCurrentStroke([]);
};
const isInsideCanvas =
!Number.isNaN(mouse.elementX) &&
mouse.elementX >= 0 &&
mouse.elementX <= (canvasBounds.width || 0) &&
mouse.elementY >= 0 &&
mouse.elementY <= (canvasBounds.height || 0);
return (
<div style={{ padding: 24, maxWidth: 700 }}>
<h2>Interactive Canvas Tool</h2>
{/* Toolbar */}
<div
ref={toolbarRef}
style={{
display: "flex",
alignItems: "center",
gap: 16,
marginBottom: 16,
padding: "12px 16px",
background: "#f8fafc",
borderRadius: 8,
flexWrap: "wrap",
}}
>
<label style={{ display: "flex", alignItems: "center", gap: 8 }}>
Color:
<input
type="color"
value={brushColor}
onChange={(e) => setBrushColor(e.target.value)}
style={{
width: 32,
height: 32,
border: "none",
borderRadius: 4,
cursor: "pointer",
}}
/>
</label>
{isEyeDropperSupported && (
<button
onClick={pickColor}
style={{
padding: "6px 12px",
background: "#e2e8f0",
border: "none",
borderRadius: 6,
cursor: "pointer",
fontSize: 13,
}}
>
Pick from Screen
</button>
)}
<label style={{ display: "flex", alignItems: "center", gap: 8 }}>
Size:
<input
type="range"
min={1}
max={20}
value={brushSize}
onChange={(e) => setBrushSize(Number(e.target.value))}
style={{ width: 100 }}
/>
<span style={{ fontSize: 13 }}>{brushSize}px</span>
</label>
<button
onClick={clearCanvas}
style={{
padding: "6px 12px",
background: "#fee2e2",
color: "#ef4444",
border: "none",
borderRadius: 6,
cursor: "pointer",
fontSize: 13,
}}
>
Clear
</button>
</div>
{/* Canvas */}
<div
ref={canvasRef}
style={{
width: "100%",
height: 400,
background: "#fff",
border: "2px solid #e2e8f0",
borderRadius: 8,
position: "relative",
overflow: "hidden",
cursor: "crosshair",
touchAction: "none",
}}
>
{/* SVG drawing surface */}
<svg
style={{ position: "absolute", inset: 0 }}
width="100%"
height="100%"
>
{/* Completed strokes */}
{strokes.map((stroke, i) => (
<polyline
key={i}
points={stroke.points.map((p) => `${p.x},${p.y}`).join(" ")}
fill="none"
stroke={stroke.color}
strokeWidth={stroke.size}
strokeLinecap="round"
strokeLinejoin="round"
/>
))}
{/* Current stroke being drawn */}
{currentStroke.length > 1 && (
<polyline
points={currentStroke.map((p) => `${p.x},${p.y}`).join(" ")}
fill="none"
stroke={brushColor}
strokeWidth={brushSize}
strokeLinecap="round"
strokeLinejoin="round"
/>
)}
</svg>
{/* Cursor preview */}
{isInsideCanvas && !pressed && (
<div
style={{
position: "absolute",
left: mouse.elementX - brushSize / 2,
top: mouse.elementY - brushSize / 2,
width: brushSize,
height: brushSize,
borderRadius: "50%",
border: `1px solid ${brushColor}`,
pointerEvents: "none",
}}
/>
)}
</div>
{/* Status bar */}
<div
style={{
marginTop: 12,
padding: "8px 16px",
background: "#f8fafc",
borderRadius: 6,
fontSize: 13,
display: "flex",
gap: 24,
color: "#64748b",
}}
>
<span>
Cursor: ({Math.round(mouse.elementX)},{" "}
{Math.round(mouse.elementY)})
</span>
<span>
Canvas: {Math.round(canvasBounds.width)} x{" "}
{Math.round(canvasBounds.height)}
</span>
<span>
State: {scratch.isScratching ? "Drawing" : pressed ? "Pressed" : "Idle"}
</span>
<span>Strokes: {strokes.length}</span>
</div>
</div>
);
}
Five hooks, each handling one responsibility:
-
useMouse
provides the cursor position for the brush preview circle -
useMousePressed
drives visual feedback and the status indicator -
useElementBounding
keeps track of the canvas dimensions for boundary checks -
useScratch
handles the actual drawing interaction with both mouse and touch -
useEyeDropper
lets the user sample colors from anywhere on screen
They share refs naturally, do not conflict, and all clean up on unmount.
